<?php
require_once 'functions.php'; require_login();$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([$_SESSION['user_id']]);$items=$q->fetchAll();$q=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?');$q->execute([$_SESSION['user_id']]);page_header('Notifications'); ?>
<section class="page-intro"><div class="eyebrow">TON ESPACE</div><h1>Notifications</h1><p>Les nouvelles de ton compte et de ta communauté.</p></section><div class="news-list"><?php foreach($items as $n): ?><article class="news-card"><div class="news-meta"><?= e(date('d/m/Y à H:i',strtotime($n['created_at']))) ?><?= !$n['is_read']?' · Nouveau':'' ?></div><p><?= e($n['content']) ?></p><?php if($n['target_url']): ?><a href="<?= e($n['target_url']) ?>">Ouvrir →</a><?php endif; ?></article><?php endforeach; ?><?php if(!$items): ?><article class="news-card">Tu es à jour. Rien à signaler pour l'instant ! ✨</article><?php endif; ?></div><?php page_footer(); ?>